import ij.*;import ij.io.*;import ij.gui.*;import ij.process.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public class ReviewMultiplexOutput {
 public static void main(String[] args)throws Exception{for(String arg:args){Path p=Path.of(arg);ImagePlus out=IJ.openImage(p.resolve("output/Results/Aligned_Stack.tif").toString());System.out.println(p.getFileName()+" dimensions="+Arrays.toString(out.getDimensions())+" calibration="+out.getCalibration());for(int s=1;s<=out.getStackSize();s++){String name=out.getStack().getSliceLabel(s);ImagePlus in=IJ.openImage(p.resolve("inputs").resolve(name).toString());System.out.println(name+" output_equals_unwarped_input="+Arrays.equals((byte[])in.getProcessor().getPixels(),(byte[])out.getStack().getProcessor(s).getPixels()));}ImagePlus in=IJ.openImage(p.resolve("inputs/Layer1_Hu.tif").toString());ImagePlus qc=IJ.openImage(p.resolve("output/Results/hu_stack.tif").toString());System.out.println("input_calibration="+in.getCalibration()+" qc_calibration="+qc.getCalibration());try(ZipFile z=new ZipFile(p.resolve("output/Results/landmark_correspondences.zip").toFile())){for(int k=1;k<=2;k++){FloatPolygon[] points=new FloatPolygon[2];for(int i=0;i<2;i++){String n="hu_"+k+(i==0?"_ref.roi":"_target.roi");byte[] b=z.getInputStream(z.getEntry(n)).readAllBytes();points[i]=new RoiDecoder(b,n).getRoi().getFloatPolygon();}FloatPolygon a=points[0],b=points[1];double dx=0,dy=0,max=0;for(int i=0;i<a.npoints;i++){dx+=b.xpoints[i]-a.xpoints[i];dy+=b.ypoints[i]-a.ypoints[i];max=Math.max(max,Math.hypot(b.xpoints[i]-a.xpoints[i],b.ypoints[i]-a.ypoints[i]));}System.out.println("pair="+k+" reference_points="+a.npoints+" target_points="+b.npoints+" mean_dx="+dx/a.npoints+" mean_dy="+dy/a.npoints+" max_pair_displacement="+max);}}}}
}
